import json
out=[]
for i,l in enumerate(open('be45aff4.jsonl')):
    d=json.loads(l)
    t=d.get('type')
    out.append('='*15+f' {i} {d.get(\"timestamp\")} {t}')
    if t in ('user','assistant'):
        m=d['message']
        c=m.get('content')
        if isinstance(c,str): out.append('TEXT: '+c[:3000])
        else:
            for b in c:
                bt=b.get('type')
                if bt=='text': out.append('TEXT: '+b['text'][:3000])
                elif bt=='thinking': out.append('THINK: '+b['thinking'][:2000])
                elif bt=='tool_use': out.append('TOOL_USE '+b['name']+' '+json.dumps(b['input'])[:1500])
                elif bt=='tool_result': out.append('TOOL_RESULT '+json.dumps(b.get('content'))[:1200])
                else: out.append(bt+' '+json.dumps(b)[:400])
    else:
        out.append(json.dumps(d)[:1200])
open('dump.txt','w').write('\n'.join(out))
print(len('\n'.join(out)))
"

