import json
def txt(m):
    c=m.get('content')
    if isinstance(c,str): return [('text',c)]
    out=[]
    for b in c or []:
        t=b.get('type')
        if t=='text': out.append(('text',b['text']))
        elif t=='thinking': out.append(('think',b.get('thinking','')))
        elif t=='tool_use': out.append(('TOOL:'+b['name'], json.dumps(b['input'])))
        elif t=='tool_result':
            cc=b.get('content')
            if isinstance(cc,list): cc=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
            out.append(('RESULT', str(cc)))
    return out
for i,l in enumerate(open('log.jsonl'),1):
    e=json.loads(l)
    ts=e.get('timestamp','')
    typ=e.get('type')
    if 'message' not in e:
        print(f'--- {i} {ts} {typ} attachment/meta')
        continue
    for k,v in txt(e['message']):
        v=' '.join(v.split())
        print(f'--- {i} {ts} {typ} [{k}] {v[:900]}')
" > flat.txt; wc -l flat.txt

