import json
def summ(c):
    if isinstance(c,str): return 'TEXT: '+c[:900]
    out=[]
    for b in c:
        t=b.get('type')
        if t=='text': out.append('TEXT: '+b['text'][:900])
        elif t=='thinking': out.append('THINK: '+b['thinking'][:400])
        elif t=='tool_use': out.append('TOOL '+b['name']+': '+json.dumps(b['input'])[:400])
        elif t=='tool_result':
            cc=b.get('content')
            s=json.dumps(cc)[:400] if not isinstance(cc,str) else cc[:400]
            out.append('RESULT: '+s)
        else: out.append(str(t))
    return ' | '.join(out)
lines=open('log.jsonl').read().splitlines()
for i,l in enumerate(lines):
    if not (75<=i<112): continue
    d=json.loads(l)
    ts=d.get('timestamp',''); ty=d.get('type'); m=d.get('message')
    sid=d.get('sessionId','')[:8]
    if ty in ('user','assistant') and m:
        print(f'--- {i} {ts} {ty} {sid}'); print(summ(m.get('content')))
    else:
        print(f'--- {i} {ts} {ty} {sid} {d.get(\"operation\",\"\")}')
"

